// Resource-only capture guard. A failed begin/end/encode must release the
// process-wide capture count and destroy any discarded partial native graph.
struct ggml_hyle_capture_guard {
    cudaStream_t stream = nullptr;
    bool counted = false;
    bool capturing = false;
    void release_count() noexcept {
        if (!counted) return;
        std::lock_guard<std::mutex> lock(ggml_cuda_lock);
        counted = false;
        if (ggml_cuda_lock_counter.fetch_sub(1, std::memory_order_relaxed) == 1)
            ggml_cuda_lock_cv.notify_all();
    }
    void begin(cudaStream_t native_stream) {
        stream = native_stream;
        {
            std::lock_guard<std::mutex> lock(ggml_cuda_lock);
            ggml_cuda_lock_counter.fetch_add(1, std::memory_order_relaxed);
            counted = true;
        }
        CUDA_CHECK(cudaStreamBeginCapture(stream, cudaStreamCaptureModeRelaxed));
        capturing = true;
    }
    void end(cudaGraph_t * graph) {
        const auto status = cudaStreamEndCapture(stream, graph);
        capturing = false;
        release_count();
        CUDA_CHECK(status);
    }
    ~ggml_hyle_capture_guard() {
        if (capturing) {
            cudaGraph_t discarded = nullptr;
            (void) cudaStreamEndCapture(stream, &discarded);
            if (discarded != nullptr) (void) cudaGraphDestroy(discarded);
        }
        release_count();
    }
};

