            const int up_idx         = with_bias ? i + 6 : i + 5;
            const int up_scale_idx   = up_idx + 4;
            const int up_bias_idx    = with_bias ? up_idx + 5 : -1;
            const int glu_idx        = with_bias ? up_idx + 6 : up_idx + 5;

            const int out_nodes[] = { glu_idx };
            ggml_op ops[13];
            if (with_bias) {
