                ops[3]  = GGML_OP_GET_ROWS;
                ops[4]  = GGML_OP_MUL;
                ops[5]  = bias_op;
                ops[6]  = op;
                ops[7]  = GGML_OP_RESHAPE;
                ops[8]  = GGML_OP_REPEAT;
                ops[9]  = GGML_OP_GET_ROWS;
                ops[10] = GGML_OP_MUL;
                ops[11] = bias_op;
                ops[12] = GGML_OP_GLU;
