// Match HYLE ordinary Unary, not the separately defined GLU formula.
// This unit is compiled by ggml-cuda-precise-unary without fast math.
static __device__ __forceinline__ float op_hyle_stable_silu(float x) {
    if (isinf(x) && x < 0) {
        return 0.0f;
    }
    const float e = expf(-fabsf(x));
    const float sigmoid = x >= 0 ? 1.0f / (1.0f + e) : e / (1.0f + e);
    return x * sigmoid;
}

