// These are four independent public BF16 boundaries, not the old GLU math.
// This instantiation belongs to the existing no-fast-math unary object.
#if !defined(GGML_USE_HIP) && !defined(GGML_USE_MUSA)
struct hyle_bf16_dual_matvec_silu_epilogue {
    static __device__ __forceinline__ float apply(float up_sum, float gate_sum) {
        const float up = __bfloat162float(__float2bfloat16_rn(up_sum));
        const float gate = __bfloat162float(__float2bfloat16_rn(gate_sum));
        const float activation = op_hyle_stable_silu(gate);
        const float rounded_activation = __bfloat162float(__float2bfloat16_rn(activation));
        // The shared carrier's final BF16 RNE store supplies the Y boundary.
        return rounded_activation * up;
    }
};

static bool hyle_bf16_dual_matvec_overlaps(const ggml_tensor * read, const ggml_tensor * dst) {
    const auto read_begin = reinterpret_cast<std::uintptr_t>(read->data);
    const auto dst_begin = reinterpret_cast<std::uintptr_t>(dst->data);
    const auto read_bytes = ggml_nbytes(read), dst_bytes = ggml_nbytes(dst);
    const auto limit = std::numeric_limits<std::uintptr_t>::max();
    if (read_bytes > limit - read_begin || dst_bytes > limit - dst_begin) {
        return true;
    }
    return read_begin < dst_begin + dst_bytes && dst_begin < read_begin + read_bytes;
}
#endif

