// The old binary nodes are separate fast-math kernels. Preserve their exact
// RN/FTZ operations in this precise TU; intrinsics without FTZ would change
// subnormal behavior, and a C++ expression could accidentally contract to FMA.
static __device__ __forceinline__ float hyle_rope_mul(float a, float b) {
    float result;
    asm("mul.rn.ftz.f32 %0, %1, %2;" : "=f"(result) : "f"(a), "f"(b));
    return result;
}

static __device__ __forceinline__ float hyle_rope_add(float a, float b) {
    float result;
    asm("add.rn.ftz.f32 %0, %1, %2;" : "=f"(result) : "f"(a), "f"(b));
    return result;
}

static __device__ __forceinline__ float hyle_rope_sub(float a, float b) {
    float result;
    asm("sub.rn.ftz.f32 %0, %1, %2;" : "=f"(result) : "f"(a), "f"(b));
    return result;
}

template <typename T>
static __global__ void hyle_explicit_rope(
        const T * data, const int32_t * positions, const float * frequencies, T * dst,
        int64_t width, int64_t heads, int64_t sequence, int64_t batch,
        int64_t dimensions, int64_t position_batches, int64_t frequency_sequences,
        bool interleaved, int64_t rotated_work, int64_t tail_elements, int64_t work) {
    ggml_cuda_pdl_lc();
    // One warp owns a phase. Trigonometry is evaluated once and reused by
    // every head (and by every B when positions are shared), without scratch.
    // All lanes reach the full-mask shuffles, including when heads < 32.
    const int lane = threadIdx.x;
    const int64_t pairs = dimensions / 2;
    ggml_cuda_pdl_sync();
    for (int64_t unit = blockIdx.x; unit < work; unit += gridDim.x) {
        if (unit < rotated_work) {
            const int64_t pair = unit % pairs;
            const int64_t row = unit / pairs;
            const int64_t s = row % sequence;
            const int64_t position_batch = row / sequence;
            float cosine = 0.0f, sine = 0.0f;
            if (lane == 0) {
                // Match cast(I32->F32), then frequency * position, in that
                // order. Do not keep the position as an exact integer longer.
                const float p = __int2float_rn(positions[s + sequence * position_batch]);
                const float f = frequencies[pair + pairs * (frequency_sequences == 1 ? 0 : s)];
                const float phase = hyle_rope_mul(f, p);
                // Separate strict full-range functions, as in old Unary.
                cosine = op_cos(phase);
                sine = op_sin(phase);
            }
            cosine = __shfl_sync(0xffffffffu, cosine, 0);
            sine = __shfl_sync(0xffffffffu, sine, 0);
            const int64_t row_heads = heads * (position_batches == 1 ? batch : 1);
            const int64_t first_component = interleaved ? 2 * pair : pair;
            const int64_t second_component = interleaved ? first_component + 1 : pair + pairs;
            for (int64_t h = lane; h < row_heads; h += 32) {
                const int64_t b = position_batches == 1 ? h / heads : position_batch;
                const int64_t head = h % heads;
                const int64_t base = width * (head + heads * (s + sequence * b));
                // Both loads precede both stores: exact dense allocator reuse
                // is safe, while partial aliases are rejected before launch.
                const float first = ggml_cuda_cast<float>(data[base + first_component]);
                const float second = ggml_cuda_cast<float>(data[base + second_component]);
                const float first_cosine = hyle_rope_mul(first, cosine);
                const float second_sine = hyle_rope_mul(second, sine);
                const float first_sine = hyle_rope_mul(first, sine);
                const float second_cosine = hyle_rope_mul(second, cosine);
                const float rotated_first = hyle_rope_sub(first_cosine, second_sine);
                const float rotated_second = hyle_rope_add(first_sine, second_cosine);
                dst[base + first_component] = ggml_cuda_cast<T>(rotated_first);
                dst[base + second_component] = ggml_cuda_cast<T>(rotated_second);
            }
        } else {
            const int64_t tail = width - dimensions;
            const int64_t linear = (unit - rotated_work) * 32 + lane;
            if (linear < tail_elements) {
                const int64_t offset = (linear / tail) * width + dimensions + linear % tail;
                if constexpr (std::is_same_v<T, float>) {
                    // Old F32 CONT/CONCAT tail is a copy, including NaN bits.
                    dst[offset] = data[offset];
                } else {
                    // The old graph widens the complete data tensor and then
                    // narrows the completed output. Keep that NaN/RNE boundary.
                    const float widened = ggml_cuda_cast<float>(data[offset]);
                    float converted;
                    // Opaque identity prevents folding the two conversions
                    // to a raw typed copy, which would retain signaling NaNs.
                    asm("mov.b32 %0, %1;" : "=f"(converted) : "f"(widened));
                    dst[offset] = ggml_cuda_cast<T>(converted);
                }
            }
        }
    }
}

static bool hyle_rope_dense_bytes(const ggml_tensor * tensor, size_t & bytes) {
    if (!tensor) {
        return false;
    }
    const size_t type_bytes = ggml_type_size(tensor->type);
    if (type_bytes == 0 || ggml_blck_size(tensor->type) != 1) {
        return false;
    }
    size_t extent = type_bytes;
    for (int d = 0; d < GGML_MAX_DIMS; ++d) {
        if (tensor->ne[d] <= 0 || tensor->nb[d] != extent ||
                uint64_t(tensor->ne[d]) > std::numeric_limits<size_t>::max() / extent) {
            return false;
        }
        extent *= size_t(tensor->ne[d]);
    }
    // All device index products below are signed int64_t, including tails.
    if (extent / type_bytes > uint64_t(std::numeric_limits<int64_t>::max())) {
        return false;
    }
    bytes = extent;
    return true;
}

static bool hyle_rope_range(const ggml_tensor * tensor, size_t bytes,
        uintptr_t & begin, uintptr_t & end) {
    begin = reinterpret_cast<uintptr_t>(tensor->data);
    if (!begin || begin % ggml_type_size(tensor->type) ||
            bytes > std::numeric_limits<uintptr_t>::max() - begin) {
        return false;
    }
    end = begin + bytes;
    return true;
}
