    // The existing float path keeps its original float2 load exactly.
    const auto load_pair = [y](int64_t index) {
        if constexpr (std::is_same_v<Y, float>) {
            return ((const float2 *) y)[index];
        } else {
            static_assert(std::is_same_v<Y, nv_bfloat16>);
            const nv_bfloat162 pair = ((const nv_bfloat162 *) y)[index];
            return make_float2(ggml_cuda_cast<float>(pair.x), ggml_cuda_cast<float>(pair.y));
