static void ggml_cuda_dispatch_gated_delta_net(ggml_backend_cuda_context & ctx, ggml_tensor * dst,
        const ggml_cuda_gated_delta_net_fused_cache * cache) {
    if (dst->src[2]->type != GGML_TYPE_F32 || dst->src[4]->type != GGML_TYPE_F32) {
        if (!ggml_cuda_supports_gated_delta_net_typed(dst)) {
            hyle::compute::ggml_cuda::bridge::fail(cudaErrorInvalidValue, "invalid typed GDN metadata");
        }
        if (dst->src[2]->type == GGML_TYPE_BF16) {
            if (dst->src[4]->type == GGML_TYPE_BF16) {
                ggml_cuda_op_gated_delta_net_impl<nv_bfloat16, nv_bfloat16>(ctx, dst, cache);
            } else {
                ggml_cuda_op_gated_delta_net_impl<nv_bfloat16, float>(ctx, dst, cache);
            }
        } else {
            ggml_cuda_op_gated_delta_net_impl<float, nv_bfloat16>(ctx, dst, cache);
        }
    } else {
        ggml_cuda_op_gated_delta_net_impl<float, float>(ctx, dst, cache);
    }
}

void ggml_cuda_op_gated_delta_net(ggml_backend_cuda_context & ctx, ggml_tensor * dst) {
    ggml_cuda_dispatch_gated_delta_net(ctx, dst, nullptr);
}

void ggml_cuda_op_gated_delta_net_fused_cache(
        ggml_backend_cuda_context & ctx, ggml_tensor * dst, ggml_cuda_gated_delta_net_fused_cache cache) {
    ggml_cuda_dispatch_gated_delta_net(ctx, dst, &cache);
}

