        const size_t element = ggml_type_size(tensor->type);
        uint64_t bytes = element;
        for (int axis = 0; axis < GGML_MAX_DIMS; ++axis) {
            if (tensor->ne[axis] <= 0 || tensor->nb[axis] > uint64_t(INT64_MAX) ||
                tensor->nb[axis] % element) return false;
            const uint64_t extent = uint64_t(tensor->ne[axis] - 1);
            if (extent && tensor->nb[axis] > (uint64_t(INT64_MAX) - bytes) / extent) return false;
            bytes += extent * tensor->nb[axis];
        }
    }
    if (C > INT64_MAX / int64_t(sizeof(float)) / K ||
        C > INT64_MAX / int64_t(sizeof(float)) / dst->ne[1] / B) return false;
