        dst->nb[0] != sizeof(float) || (dst->ne[1] > 1 && dst->nb[1] < uint64_t(C) * sizeof(float))) return false;
    const uint64_t output_batch_bytes = uint64_t(dst->ne[1] - 1) * dst->nb[1] + uint64_t(C) * sizeof(float);
    if (B > 1 && dst->nb[2] < output_batch_bytes) return false;
    if (x->type == GGML_TYPE_F32) {
        // Preserve the old F32 carrier's exact time-contiguous layout domain.
        return x->nb[0] == sizeof(float) && x->nb[1] == uint64_t(W) * sizeof(float) &&
            (B == 1 || x->nb[2] >= uint64_t(W) * uint64_t(C) * sizeof(float));
    }
    const uint64_t channel_bytes = uint64_t(C) * sizeof(nv_bfloat16);
    // Native BF16 [W,C,B] is the permutation of channel-contiguous rows.
    // Padding is legal, broadcast/overlapping time or batch rows are not.
    if (x->nb[1] != sizeof(nv_bfloat16) || x->nb[0] < channel_bytes ||
        uint64_t(W - 1) > (uint64_t(INT64_MAX) - channel_bytes) / x->nb[0]) return false;
    const uint64_t batch_bytes = uint64_t(W - 1) * x->nb[0] + channel_bytes;
    return (B == 1 || x->nb[2] >= batch_bytes) && ggml_is_contiguous(dst);
